using CommanderOwnerConsent;using CommanderNativeIssuer;using System.Security.Cryptography;using System.Text;using System.Text.Json;using System.Text.RegularExpressions;
namespace CommanderOwnerFinalizeJ;
internal static class Program
{
 static string phase="Arguments",owner="",jId="";static bool ownIntent,ownerValidated;static string State(string name)=>Path.Combine(JContract.StateRoot,name);
