 static byte[] Outcome(string status,string code,int hr=0,string kind="None")=>JContract.Json(w=>{w.WriteString("schema","RC_OWNER_J_OUTCOME_V1");w.WriteString("status",status);w.WriteString("code",code);w.WriteString("phase",phase);w.WriteNumber("hresult",hr);w.WriteString("hresultHex","0x"+unchecked((uint)hr).ToString("X8"));w.WriteString("exceptionType",kind);w.WriteString("jId",jId);w.WriteBoolean("automaticRetryAllowed",false);w.WriteBoolean("ownedHelperCleanupUncertain",JIO.CleanupUncertain);w.WriteBoolean("privateKeysOpened",false);w.WriteBoolean("installedCommanderChanged",false);w.WriteBoolean("jobsStoppedOrReplayed",false);});
 static void Emit(byte[] b,bool error=false){if(error)Console.Error.WriteLine(Encoding.UTF8.GetString(b));else Console.WriteLine(Encoding.UTF8.GetString(b));}
 static int Main(string[] args)
 {
  string mode="";try{
   if(args.Length==1&&args[0]=="--diagnose"){var t=WindowsGuard.Inspect();Emit(JContract.Json(w=>{w.WriteString("status","ORDINARY_DIAGNOSTIC_NO_AUTHORITY_IO");w.WriteBoolean("elevated",t.Elevated);w.WriteBoolean("administrator",t.Administrator);w.WriteNumber("session",t.SessionId);w.WriteNumber("integrityRid",t.IntegrityRid);w.WriteBoolean("protectedPathsOpened",false);}));return 0;}
   ConsentCore.Need(args.Length==3&&args[0] is "--finalize-staged" or "--rollback-finalized","J_FINITE_ARGUMENTS");mode=args[0];owner=args[1];ConsentCore.Need(Regex.IsMatch(owner,"^S-1-5-21-[0-9-]+$")&&Regex.IsMatch(args[2],"^[a-f0-9]{64}$"),"J_ARGUMENT_BINDING");
   phase="OwnerToken";WindowsGuard.RequireOwner(WindowsGuard.Inspect(),owner);ownerValidated=true; // MUST precede all authority/source/key access.
   phase="OwnNativeImage";var path=Environment.ProcessPath??"";WindowsGuard.NoReparse(path);using var self=new FileStream(path,FileMode.Open,FileAccess.Read,FileShare.Read);var bytes=WindowsGuard.Read(self);ConsentCore.Need(JContract.Hex(bytes)==args[2],"J_REVIEWED_SELF_PIN_REQUIRED");NativeImage.ValidateNativePe(bytes);
   phase="ReconcileExactIStage";using var stage=new IStage(owner);var result=mode=="--finalize-staged"?Finalize(stage,args[2]):Rollback(stage,args[2]);Emit(result);return 0;
  }catch(Exception e){var fault=e as JFault;phase=fault?.Phase??phase;var code=e is ConsentFault?e.Message:fault?.Message??"J_NATIVE_FAILURE";if(!JIO.Safe(code))code="J_NATIVE_FAILURE";var kind=fault?.Kind??e.GetType().Name;if(!JIO.Safe(kind))kind="Exception";var hr=fault?.NativeHResult??e.HResult;var result=Outcome("FAILED_NO_RETRY",code,hr,kind);var persisted=false;if(ownIntent){try{var name=mode=="--rollback-finalized"?"finalization-j.rollback.outcome.json":"finalization-j.outcome.json";JIO.Write(State(name),result,owner);persisted=true;}catch{e.Data["outcomePersistenceUncertain"]=true;}}if(ownerValidated&&!persisted){MessageBoxW(0,"تکمیل متوقف شد؛ دوباره اجرا نکنید.\nکد: "+code+"\nمرحله: "+phase+"\nHRESULT: 0x"+unchecked((uint)hr).ToString("X8")+"\nرسید عمومی ثبت نشد؛ این پیام را به بررسی‌کننده بدهید.","Remote Commander — نتیجهٔ تکمیل J",0x00100000|0x00080000|0x00000010);}Emit(result,true);return 2;}
 }
 static byte[] Intent(IStage s,string pin)=>JContract.Json(w=>{w.WriteString("schema","RC_OWNER_J_INTENT_V1");w.WriteString("ownerSid",owner);w.WriteNumber("ownerSessionId",s.Session);w.WriteString("bundleSha256",JContract.BundleSha);w.WriteString("enrollmentId",s.Enrollment);w.WriteString("jId",jId);w.WriteString("selfSha256",pin);w.WriteString("scriptSha256",JContract.Hex(JContract.Script()));w.WritePropertyName("iInputPins");w.WriteStartObject();foreach(var row in s.Pins.OrderBy(x=>x.Key,StringComparer.Ordinal))w.WriteString(row.Key,row.Value);w.WriteEndObject();});
 static byte[] Registration(IStage s,byte[] prepared,string pin)=>JContract.Json(w=>{w.WriteString("schema","RC_OWNER_J_REGISTRATION_INTENT_V1");w.WriteString("ownerSid",owner);w.WriteString("bundleSha256",JContract.BundleSha);w.WriteString("enrollmentId",s.Enrollment);w.WriteString("jId",jId);w.WriteString("preparedSha256",JContract.Hex(prepared));w.WriteString("scriptSha256",JContract.Hex(JContract.Script()));w.WriteString("selfSha256",pin);});
 static byte[] Finalize(IStage s,string pin)
 {
  phase="RequireJAbsent";foreach(var f in new[]{"finalization-j.intent.json","finalization-j.ps1","task-j.prepared.json","task-j.registration.intent.json","task-j.attested.json","finalization-j.complete.json","finalization-j.outcome.json"})JIO.Absent(State(f));JIO.Absent(Path.Combine(JContract.ProgramRoot,"client-policy.json"));s.Revalidate();
  jId="finalize:"+Guid.NewGuid().ToString("N");phase="CreateJIntent";var intent=Intent(s,pin);JIO.Write(State("finalization-j.intent.json"),intent,owner);ownIntent=true;using var heldIntent=JIO.Hold(State("finalization-j.intent.json"),intent);
  phase="StageFixedJScript";var script=JContract.Script();JIO.Write(State("finalization-j.ps1"),script,owner);using var heldScript=JIO.Hold(State("finalization-j.ps1"),script);
  phase="InspectTaskAbsent";using(var d=ConsentCore.Strict(JIO.Invoke(State("finalization-j.ps1"),"inspect"))){ConsentCore.Fields(d.RootElement,"status");ConsentCore.Need(ConsentCore.Text(d.RootElement,"status")=="TASK_ABSENT_NO_MUTATION","J_TASK_PRESENT_STOP_NO_OVERWRITE");}
  phase="PrepareJTask";var prepared=JContract.Prepared(owner,s.Enrollment,jId);JIO.Write(State("task-j.prepared.json"),prepared,owner);using var hp=JIO.Hold(State("task-j.prepared.json"),prepared);var reg=Registration(s,prepared,pin);JIO.Write(State("task-j.registration.intent.json"),reg,owner);using var hr=JIO.Hold(State("task-j.registration.intent.json"),reg);s.Revalidate();
  phase="CreateOnlyAndAttestJTask";var attested=JIO.Invoke(State("finalization-j.ps1"),"finalize");using(var d=ConsentCore.Strict(attested)){var a=d.RootElement;ConsentCore.Fields(a,"schema","status","taskName","jId","xml","sddl","nativeSystemSid","nativeLogonType","started");ConsentCore.Need(ConsentCore.Text(a,"schema")=="RC_OWNER_J_TASK_ATTESTED_V1"&&ConsentCore.Text(a,"status")=="TASK_CREATED_ATTESTED_NOT_STARTED"&&ConsentCore.Text(a,"taskName")==JContract.TaskName&&ConsentCore.Text(a,"jId")==jId&&ConsentCore.Text(a,"nativeSystemSid")=="S-1-5-18"&&a.GetProperty("nativeLogonType").GetInt32()==5&&!a.GetProperty("started").GetBoolean(),"J_NATIVE_ATTESTATION_BINDING");}
  phase="PersistJAttestation";JIO.Write(State("task-j.attested.json"),attested,owner);using var ha=JIO.Hold(State("task-j.attested.json"),attested);s.Revalidate();
  phase="PublishClientPolicyAfterAttestation";var client=Path.Combine(JContract.ProgramRoot,"client-policy.json");JIO.Absent(client);JIO.Write(client,s.ClientPolicy,owner);using var hc=JIO.Hold(client,s.ClientPolicy);
  phase="CompleteJ";var completion=JContract.Json(w=>{w.WriteString("schema","RC_OWNER_J_COMPLETION_V1");w.WriteString("ownerSid",owner);w.WriteString("jId",jId);w.WriteString("enrollmentId",s.Enrollment);w.WriteString("bundleSha256",JContract.BundleSha);w.WriteString("attestedSha256",JContract.Hex(attested));w.WriteString("clientPolicySha256",JContract.Hex(s.ClientPolicy));w.WriteBoolean("taskStarted",false);w.WriteBoolean("privateKeysOpened",false);w.WriteBoolean("iRecordsPreserved",true);});JIO.Write(State("finalization-j.complete.json"),completion,owner);var result=Outcome("COMPLETE","J_TASK_ATTESTED_CLIENT_PUBLISHED_NOT_STARTED");JIO.Write(State("finalization-j.outcome.json"),result,owner);return result;
 }
 static byte[] Rollback(IStage s,string pin)
 {
  phase="ValidateJRollbackEvidence";var holds=new List<FileStream>();try{
   var exists=File.Exists(State("finalization-j.intent.json"));if(exists){var f=WindowsGuard.OpenProtected(State("finalization-j.intent.json"),32768);holds.Add(f);var b=WindowsGuard.Read(f);using var d=ConsentCore.Strict(b);jId=JContract.OpaqueId(d.RootElement,"jId","^finalize:[a-f0-9]{32}$");ConsentCore.Need(b.SequenceEqual(Intent(s,pin)),"J_ROLLBACK_INTENT_CHANGED");ownIntent=true;}
   // A distinct fixed recovery helper allows inspection after an interrupted J script copy.
   var script=JContract.Script();var helper=State("finalization-j-rollback-helper.ps1");if(!File.Exists(helper))JIO.Write(helper,script,owner);holds.Add(JIO.Hold(helper,script));
   var prepared=JContract.Prepared(owner,s.Enrollment,jId);var p=State("task-j.prepared.json");var r=State("task-j.registration.intent.json");if(File.Exists(p)){ConsentCore.Need(exists,"J_ROLLBACK_ORPHAN_PREPARED");holds.Add(JIO.Hold(p,prepared));}if(File.Exists(r)){ConsentCore.Need(exists&&File.Exists(p),"J_ROLLBACK_ORPHAN_REGISTRATION");holds.Add(JIO.Hold(r,Registration(s,prepared,pin)));}s.Revalidate();
   phase="RollbackExactIdleJTask";var raw=JIO.Invoke(helper,"rollback");using var doc=ConsentCore.Strict(raw);ConsentCore.Fields(doc.RootElement,"status");var status=ConsentCore.Text(doc.RootElement,"status");ConsentCore.Need(status is "TASK_ABSENT_DEACTIVATED_FILES_KEYS_PRESERVED" or "TASK_REMOVED_FILES_KEYS_PRESERVED","J_ROLLBACK_RESULT");var result=Outcome("COMPLETE",status);var outPath=State("finalization-j.rollback.complete.json");if(!File.Exists(outPath))JIO.Write(outPath,result,owner);else{using var previous=WindowsGuard.OpenProtected(outPath,32768);using var old=ConsentCore.Strict(WindowsGuard.Read(previous));ConsentCore.Need(ConsentCore.Text(old.RootElement,"schema")=="RC_OWNER_J_OUTCOME_V1"&&ConsentCore.Text(old.RootElement,"status")=="COMPLETE"&&ConsentCore.Text(old.RootElement,"jId")==jId,"J_ROLLBACK_RECEIPT_CHANGED");}return result;
  }finally{foreach(var f in holds)f.Dispose();}
 }
